const feeds = [
  { layer: 'inflation_activity', sourceId: 'ibge_releases_general', sourceName: 'IBGE - Releases gerais', feedUrl: '', weight: 90 },
  { layer: 'inflation_activity', sourceId: 'ibge_ipca_tag', sourceName: 'IBGE - Tag IPCA', feedUrl: '', weight: 92 },
  { layer: 'market_news', sourceId: 'uol_economia_home', sourceName: 'UOL Economia', feedUrl: '', weight: 74 },
  { layer: 'market_news', sourceId: 'uol_economia_latest', sourceName: 'UOL - Ultimas de Economia', feedUrl: '', weight: 78 },
  { layer: 'market_news', sourceId: 'uol_investments', sourceName: 'UOL - Investimentos / Bolsas e Acoes', feedUrl: '', weight: 80 },
  { layer: 'fiscal_policy', sourceId: 'tesouro_news', sourceName: 'Tesouro Nacional - Noticias', feedUrl: '', weight: 84 },
  { layer: 'fiscal_policy', sourceId: 'tesouro_rtn', sourceName: 'Tesouro Nacional - RTN', feedUrl: '', weight: 86 },
  { layer: 'fiscal_policy', sourceId: 'fazenda_news', sourceName: 'Ministerio da Fazenda - Noticias', feedUrl: '', weight: 86 },
  { layer: 'corporate_weights', sourceId: 'petrobras_news_agency', sourceName: 'Petrobras - Agencia de Noticias', feedUrl: '', weight: 78 },
  { layer: 'corporate_weights', sourceId: 'vale_investor_market', sourceName: 'Vale - Informacoes para o mercado', feedUrl: '', weight: 78 },
  { layer: 'corporate_weights', sourceId: 'vale_press_releases', sourceName: 'Vale - Press Releases', feedUrl: '', weight: 76 }
];

// Banco Central do Brasil moved to a dedicated direct-API workflow.
// Paste only RSS or RSS.app URLs into feedUrl. Empty feeds are ignored.
return feeds
  .filter(feed => /^https?:\/\//i.test(String(feed.feedUrl || '')))
  .map(feed => ({ json: feed }));

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const now = Date.now();
const ttlMs = 6 * 60 * 60 * 1000;

const containsAny = (text, terms) => terms.some(term => text.includes(term));
const countHits = (text, terms) => terms.filter(term => text.includes(term)).length;
const clean = value => String(value || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

const hawkishTerms = ['copom', 'selic', 'juros', 'banco central', 'bc', 'inflacao', 'ipca', 'ipca-15', 'expectativas', 'desancoragem', 'ata', 'comunicado'];
const fiscalTerms = ['fiscal', 'deficit', 'superavit', 'arcabouco', 'tesouro', 'fazenda', 'divida', 'arrecadacao', 'contingenciamento', 'meta fiscal', 'resultado primario'];
const corporateTerms = ['petrobras', 'petr4', 'combustiveis', 'dividendos', 'vale', 'vale3', 'minerio', 'china'];
const stressTerms = ['piora', 'acima do esperado', 'pressiona', 'alta', 'aumento', 'risco', 'alerta', 'revisao', 'bloqueio', 'corte de gastos', 'queda de arrecadacao'];
const reliefTerms = ['melhora', 'abaixo do esperado', 'alivia', 'queda', 'corte de juros', 'reduz', 'superavit', 'desacelera', 'acordo', 'recuo'];

const candidates = [];
for (const item of items) {
  const j = item.json || {};
  const title = clean(j.title || j.name);
  const summary = clean(j.contentSnippet || j.content || j.description || j.summary);
  const link = String(j.link || j.guid || '').trim();
  const text = `${title} ${summary}`.toLowerCase();
  const publishedRaw = j.isoDate || j.pubDate || j.pubdate || j.published || '';
  const publishedAt = publishedRaw ? new Date(publishedRaw) : null;
  const publishedTs = publishedAt && !Number.isNaN(publishedAt.getTime()) ? publishedAt.getTime() : now;
  const ageHours = Math.max(0, (now - publishedTs) / 3600000);
  if (!title || ageHours > 72) continue;

  const hawkishHits = countHits(text, hawkishTerms);
  const fiscalHits = countHits(text, fiscalTerms);
  const corporateHits = countHits(text, corporateTerms);
  const stressHits = countHits(text, stressTerms);
  const reliefHits = countHits(text, reliefTerms);

  let score = 30;
  score += Math.min(hawkishHits, 3) * 16;
  score += Math.min(fiscalHits, 3) * 15;
  score += Math.min(corporateHits, 2) * 10;
  score += Math.min(stressHits, 2) * 12;
  score += Math.min(reliefHits, 2) * 8;
  if ((hawkishHits || fiscalHits) && stressHits) score += 18;
  if (hawkishHits && fiscalHits) score += 12;
  if (ageHours <= 1) score += 16;
  else if (ageHours <= 4) score += 10;
  else if (ageHours <= 12) score += 5;
  else if (ageHours > 48) score -= 20;
  score = Math.max(0, Math.min(140, score));

  const isRelief = reliefHits > stressHits;
  const level = score >= 85 ? 'RED' : score >= 70 ? 'ORANGE' : score >= 55 ? 'YELLOW' : 'GREEN';
  const levelLabel = level === 'RED' ? 'VERMELHO' : level === 'ORANGE' ? 'LARANJA' : level === 'YELLOW' ? 'ATENCAO' : 'SEM SINAL';
  const tendency = isRelief ? 'vies de alta para WIN se dolar e DI confirmarem alivio' : 'pressao vendedora para WIN se dolar e DI seguirem firmes';
  const conviction = score >= 95 ? 'alta' : score >= 70 ? 'media-alta' : 'baixa';
  const win_read = isRelief
    ? 'WIN pode buscar alta se sustentar VWAP e romper maxima da abertura com dolar cedendo.'
    : 'WIN tende a sofrer se perder VWAP/minima da abertura com dolar e DI subindo.';
  const dollar_read = isRelief
    ? 'Dolar pode aliviar se a leitura reduzir risco fiscal, inflacionario ou de juros.'
    : 'Dolar pode ganhar forca se a noticia aumentar risco fiscal, inflacao ou juros.';
  const us_read = 'Global entra como confirmacao secundaria; o gatilho aqui e Brasil Local.';
  const confirmation = isRelief
    ? 'Confirmar com DI caindo, dolar cedendo e WIN acima da VWAP.'
    : 'Confirmar com DI subindo, dolar firme e WIN abaixo da VWAP.';
  const invalidation = isRelief
    ? 'Invalida se dolar voltar a subir e WIN perder VWAP.'
    : 'Invalida se DI e dolar aliviarem e WIN recuperar VWAP.';
  const reason = isRelief
    ? 'Noticia local com potencial de alivio em juros, fiscal, inflacao ou pesos do indice.'
    : 'Noticia local com potencial de pressionar juros, dolar, fiscal ou pesos do indice.';

  const key = `${title.toLowerCase()}|${link}`;
  const seenAt = staticData.seen[key];
  if (seenAt && now - seenAt < ttlMs) continue;

  candidates.push({ json: {
    alert_type: 'brazil_local', regime: 'BR_LOCAL', level, levelLabel, score,
    title, normalizedTitle: title, summary, link, ageHours: Math.round(ageHours * 10) / 10,
    tendency, conviction, win_read, dollar_read, us_read, confirmation, invalidation, reason,
    source: j.creator || j.source || 'RSS.app Brazil Local', channels: ['telegram', 'dashboard'], generatedAt: new Date().toISOString(), dedupeKey: key
  }});
}

for (const [key, ts] of Object.entries(staticData.seen)) {
  if (now - ts > ttlMs) delete staticData.seen[key];
}

const actionable = candidates.filter(item => item.json.score >= 55);
if (!actionable.length) return [];
actionable.sort((a, b) => (b.json.score - a.json.score) || (a.json.ageHours - b.json.ageHours));
const winner = actionable[0];
staticData.seen[winner.json.dedupeKey] = now;
winner.json.discordText = `**BRASIL LOCAL | ${winner.json.levelLabel}**\n\n**Titulo:** ${winner.json.title}\n**Tendencia:** ${winner.json.tendency}\n**Conviccao:** ${winner.json.conviction}\n\n**Leitura WIN:** ${winner.json.win_read}\n**Leitura Dolar:** ${winner.json.dollar_read}\n**Leitura global:** ${winner.json.us_read}\n\n**Confirmar:** ${winner.json.confirmation}\n**Invalidar:** ${winner.json.invalidation}\n\n**Fonte:** ${winner.json.source}\n**Link:** ${winner.json.link || '-'}\n**Motivo:** ${winner.json.reason}`;
return [winner];
